<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\TenantTermsOfUseTextVO;
use Civi\Lughauth\Features\Access\TenantTermsOfUse\Domain\ValueObject\Holder\TenantTermsOfUseTextAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TenantTermsOfUseTextAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class TenantTermsOfUseTextAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getText returns null on a freshly created holder.
         */
        public function testTextNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithTenantTermsOfUseTextAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isTextAssigned());
            $this->assertNull($holder->getText());
        }
}
class ImplWithTenantTermsOfUseTextAttributeHolderUnitTest
{
  use TenantTermsOfUseTextAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedTextRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultText();
    }}
